func TestManagerKek(t *testing.T) {
	m := NewManager()

	var kek Kek
	kek[0] = 0xAB
	m.SetKek(kek)

	if m.GetKek() != kek {
		t.Error("KEK not set correctly")
	}
	if m.GetKekFrameCounter() != 0 {
		t.Error("KEK frame counter should be 0 after SetKek")
	}

	m.IncrementKekFrameCounter()
	m.IncrementKekFrameCounter()
	if m.GetKekFrameCounter() != 2 {
		t.Errorf("KEK frame counter: got %d, want 2", m.GetKekFrameCounter())
	}
}

func TestManagerPskc(t *testing.T) {
	m := NewManager()

	if m.IsPskcSet() {
		t.Error("PSKc should not be set initially")
	}

	var pskc Pskc
	pskc[0] = 0x42
	m.SetPskc(pskc)

	if !m.IsPskcSet() {
		t.Error("PSKc should be set after SetPskc")
	}
	if m.GetPskc() != pskc {
		t.Error("PSKc value mismatch")
	}
}

func TestManagerGetTemporaryKeys(t *testing.T) {
	m := NewManager()
	var nk NetworkKey
	copy(nk[:], mustDecodeHex("00112233445566778899aabbccddeeff"))
	m.networkKey = nk

	dk := m.ComputeKeys(42)

	mle := m.GetTemporaryMleKey(42)
	if mle != dk.MleKey {
		t.Error("GetTemporaryMleKey mismatch")
	}

	mac := m.GetTemporaryMacKey(42)
	if mac != dk.MacKey {
		t.Error("GetTemporaryMacKey mismatch")
	}
}

func TestManagerSetSecurityPolicyClamp(t *testing.T) {
	m := NewManager()

	sp := m.GetSecurityPolicy()
	sp.RotationTime = 1 // Below minimum.
	m.SetSecurityPolicy(sp)

	got := m.GetSecurityPolicy()
	if got.RotationTime != MinKeyRotationTime {
		t.Errorf("rotation time should be clamped to %d, got %d", MinKeyRotationTime, got.RotationTime)
	}
}

func TestManagerSetSecurityPolicyGuardRecalc(t *testing.T) {
	m := NewManager()

	sp := m.GetSecurityPolicy()
	sp.RotationTime = 100
	m.SetSecurityPolicy(sp)

	// Guard time should be 93% of 100 = 93.
	if m.GetKeySwitchGuardTime() != 93 {
		t.Errorf("guard time: got %d, want 93", m.GetKeySwitchGuardTime())
	}
}

func TestManagerKeyRotation(t *testing.T) {
	m := NewManager()
	m.Start()

	sp := m.GetSecurityPolicy()
	sp.RotationTime = 5 // Rotate every 5 hours.
	m.SetSecurityPolicy(sp)

	// Guard time should be 93% of 5 = 4 (integer division).
	if m.GetKeySwitchGuardTime() != 4 {
		t.Errorf("guard time: got %d, want 4", m.GetKeySwitchGuardTime())
	}

	// Tick 4 times — not yet at rotation time.
	for range 4 {
		m.HandleKeyRotationTick()
	}
	if m.GetCurrentKeySequence() != 0 {
		t.Errorf("should not rotate yet: seq=%d", m.GetCurrentKeySequence())
	}

	// 5th tick triggers rotation.
	m.HandleKeyRotationTick()
	if m.GetCurrentKeySequence() != 1 {
		t.Errorf("should rotate: seq=%d, want 1", m.GetCurrentKeySequence())
	}

	// After rotation, hours counter resets.
	if m.GetHoursSinceKeyRotation() != 0 {
		t.Errorf("hours since rotation: got %d, want 0", m.GetHoursSinceKeyRotation())
	}
}

func TestManagerUpdateKeyMaterial(t *testing.T) {
	m := NewManager()
	var nk NetworkKey
	copy(nk[:], mustDecodeHex("00112233445566778899aabbccddeeff"))
	m.networkKey = nk
	m.keySequence = 42

	m.UpdateKeyMaterial()

	dk := m.ComputeKeys(42)
	if m.GetCurrentMleKey() != dk.MleKey {
		t.Error("UpdateKeyMaterial did not set correct MLE key")
	}
}
